import{Renderer}from'./engine.js';
import{Scene}from'./scene.js';
import{Fight,STYLES}from'./combat.js';
const $=id=>document.getElementById(id);
class AudioFX{
 constructor(){this.ctx=null;this.enabled=false;}
 init(){try{this.ctx ||= new(window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume();}catch{this.enabled=false;}}
 tone(freq,duration,volume=.05,type='sine',to=freq){if(!this.enabled||!this.ctx)return;const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,to),c.currentTime+duration);g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration);}
 hit(blocked,special){if(!this.enabled||!this.ctx)return;this.tone(blocked?420:105,blocked?.1:.19,special?.14:.08,blocked?'triangle':'sine',blocked?190:35);const c=this.ctx,length=Math.floor(c.sampleRate*.13),buffer=c.createBuffer(1,length,c.sampleRate),d=buffer.getChannelData(0);for(let i=0;i<length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/length,3);const source=c.createBufferSource(),gain=c.createGain(),filter=c.createBiquadFilter();source.buffer=buffer;gain.gain.value=blocked?.08:.2;filter.type='lowpass';filter.frequency.value=blocked?3000:1700;source.connect(filter);filter.connect(gain);gain.connect(c.destination);source.start();}
 cue(which){if(which==='fight'){this.tone(220,.6,.08,'sine',110);this.tone(440,.4,.035,'triangle',220);}else if(which==='win'){this.tone(440,.9,.07);setTimeout(()=>this.tone(554,.7,.06),120);setTimeout(()=>this.tone(660,1,.05),240);}else if(which==='round'){this.tone(330,.75,.05,'sine',300);}else if(which==='special'){this.tone(160,.3,.06,'triangle',620);}else if(which==='attack'){this.tone(170,.07,.01,'triangle',340);}else this.tone(70,.6,.07,'triangle',35);}
}
const audio=new AudioFX();let scene,renderer,fight,selected='drunk',noticeUntil=0,calloutUntil=0,pausedForHelp=false,frame=0,last=performance.now();const held=new Set(),pointerKeys=new Map();
function callout(small,main,seconds=1.2){$('callout-small').textContent=small;$('callout-main').textContent=main;$('callout').style.opacity=1;calloutUntil=performance.now()+seconds*1000;}
function notice(text,seconds=1){$('hit-label').textContent=text;noticeUntil=performance.now()+seconds*1000;}
function onEvent(e){if(e.type==='round'){callout('ROUND '+String(e.round).padStart(2,'0'),'構え',1.9);audio.cue('round');}
 else if(e.type==='fight'){callout('FIGHT','始め',.9);audio.cue('fight');}
 else if(e.type==='attack'){if(e.move==='special'){notice(STYLES[e.fighter.style].skill,1.4);audio.cue('special');}else audio.cue('attack');}
 else if(e.type==='notready')notice('氣を溜めて、奥義を。',.9);
 else if(e.type==='hit'){scene?.spark(e);audio.hit(e.blocked,e.special);if(e.fighter===fight.p){if(e.blocked)notice('GUARD',.5);else if(e.combo>=2)notice(e.combo+' HITS'+(e.special?'\n'+STYLES[e.fighter.style].skill:''),1.05);else if(e.counter)notice('COUNTER',.8);}}
 else if(e.type==='roundend'){callout(e.winner?(e.winner===fight.p?'YOU WIN THE ROUND':'CPU WINS THE ROUND'):'DRAW',e.reason,3.1);audio.cue(e.winner===fight.p?'win':'lose');clearKeys();}
 else if(e.type==='matchend'){const won=e.winner===fight.p;$('result-title').textContent=won?'勝利':'再挑戦';$('result-detail').textContent=(won?'見事な手合わせ。':'次の一撃で、流れを変えよう。')+'　'+fight.p.wins+' − '+fight.cpu.wins;$('result').hidden=false;$('touch-controls').hidden=true;$('pause').hidden=true;$('rematch').focus();}
}
function refreshNames(){for(const [side,f]of[['left',fight.p],['right',fight.cpu]]){$(side+'-name').textContent=STYLES[f.style].name;$(side+'-en').textContent=STYLES[f.style].en;}}
function select(style){selected=style;fight.select(style);$('choose-drunk').classList.toggle('selected',style==='drunk');$('choose-wing').classList.toggle('selected',style==='wing');$('choose-drunk').setAttribute('aria-pressed',String(style==='drunk'));$('choose-wing').setAttribute('aria-pressed',String(style==='wing'));refreshNames();}
function start(){audio.init();clearKeys();$('selection').hidden=true;$('result').hidden=true;$('pause-panel').hidden=true;$('pause').hidden=false;$('touch-controls').hidden=false;$('game').classList.add('playing');$('start').blur();fight.start(selected);refreshNames();}
function goBack(){clearKeys();fight.phase='select';fight.paused=false;fight.clock=60;fight.round=1;select(selected);$('selection').hidden=false;$('result').hidden=true;$('pause-panel').hidden=true;$('pause').hidden=true;$('touch-controls').hidden=true;$('game').classList.remove('playing');$('callout').style.opacity=0;$('hit-label').textContent='';calloutUntil=0;noticeUntil=0;$('start').focus();}
function setPaused(value){if(fight.phase==='select'||fight.phase==='matchend')return;fight.paused=value;clearKeys();$('pause-panel').hidden=!value;$('pause').textContent=value?'▶':'Ⅱ';$('pause').setAttribute('aria-label',value?'再開':'一時停止');$('touch-controls').hidden=value;if(value)$('resume').focus();}
function clearKeys(){held.clear();pointerKeys.clear();document.querySelectorAll('[data-key]').forEach(b=>b.classList.remove('pressed'));}
function keyPress(code){if(fight.paused||$('help-dialog').open)return;const map={KeyJ:'punch',KeyK:'kick',KeyL:'special'};if(map[code])fight.attack(fight.p,map[code]);}
function ui(){for(const [side,f]of[['left',fight.p],['right',fight.cpu]]){$(side+'-health').style.transform='scaleX('+f.hp/100+')';$(side+'-damage').style.transform='scaleX('+f.hp/100+')';$(side+'-energy').style.width=f.energy+'%';$(side+'-energy').parentElement.classList.toggle('ready',f.energy>=100);$(side+'-health').parentElement.setAttribute('aria-label','体力 '+Math.ceil(f.hp));[...$(side+'-wins').children].forEach((el,i)=>el.classList.toggle('won',i<f.wins));}$('timer').textContent=String(Math.ceil(fight.clock)).padStart(2,'0');$('round').textContent='ROUND '+String(fight.round).padStart(2,'0');$('timer').style.color=fight.clock<10?'#f0a172':'';const now=performance.now();if(now>calloutUntil)$('callout').style.opacity=0;if(now>noticeUntil)$('hit-label').textContent='';const special=document.querySelector('[data-key="KeyL"]');special.style.opacity=fight.p.energy>=100?'1':'.55';special.setAttribute('aria-label',fight.p.energy>=100?'奥義、使用可能':'奥義、氣 '+Math.floor(fight.p.energy)+'%');}
function loop(now){const dt=Math.min((now-last)/1000,.04);last=now;const x=(held.has('KeyD')||held.has('ArrowRight')?1:0)-(held.has('KeyA')||held.has('ArrowLeft')?1:0),z=(held.has('KeyS')||held.has('ArrowDown')?1:0)-(held.has('KeyW')||held.has('ArrowUp')?1:0);fight.tick(dt,{x,z,guard:held.has('Space')});if(!fight.paused)scene.render(fight,dt);if(frame++%2===0)ui();requestAnimationFrame(loop);}
try{renderer=new Renderer($('arena'));scene=new Scene(renderer);fight=new Fight(onEvent);
 $('choose-drunk').onclick=()=>select('drunk');$('choose-wing').onclick=()=>select('wing');$('start').onclick=start;$('rematch').onclick=start;$('back').onclick=goBack;$('pause-back').onclick=goBack;$('pause').onclick=()=>setPaused(!fight.paused);$('resume').onclick=()=>setPaused(false);
 $('sound').onclick=()=>{audio.init();audio.enabled=!audio.enabled;$('sound').textContent=audio.enabled?'音 ON':'音 OFF';$('sound').setAttribute('aria-label',audio.enabled?'音をオフにする':'音をオンにする');if(audio.enabled)audio.cue('round');};
 $('help').onclick=()=>{clearKeys();pausedForHelp=!fight.paused&&['fight','intro','roundend'].includes(fight.phase);if(pausedForHelp)fight.paused=true;$('help-dialog').showModal();};
 document.querySelectorAll('.close-dialog,.close-help').forEach(b=>b.onclick=()=>$('help-dialog').close());$('help-dialog').addEventListener('close',()=>{if(pausedForHelp)fight.paused=false;pausedForHelp=false;clearKeys();});
 window.addEventListener('keydown',e=>{if($('help-dialog').open)return;if(e.code==='Escape'){e.preventDefault();setPaused(!fight.paused);return;}if(e.code==='Enter'&&fight.phase==='select'){e.preventDefault();start();return;}if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowLeft','ArrowDown','ArrowRight','KeyJ','KeyK','KeyL','Space'].includes(e.code)){if(fight.phase!=='select')e.preventDefault();if(!e.repeat){held.add(e.code);keyPress(e.code);}}});window.addEventListener('keyup',e=>held.delete(e.code));
 document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);const key=b.dataset.key;pointerKeys.set(e.pointerId,key);held.add(key);keyPress(key);b.classList.add('pressed');audio.init();});const release=e=>{const key=pointerKeys.get(e.pointerId);pointerKeys.delete(e.pointerId);if(![...pointerKeys.values()].includes(key))held.delete(key);b.classList.remove('pressed');};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);});
 window.addEventListener('blur',()=>{clearKeys();if(!fight.paused&&['fight','intro','roundend'].includes(fight.phase))setPaused(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!fight.paused&&['fight','intro','roundend'].includes(fight.phase))setPaused(true);});window.addEventListener('resize',()=>{renderer.resize();if(fight.paused)scene.render(fight,0);});$('arena').addEventListener('webglcontextlost',e=>{e.preventDefault();fight.paused=true;$('error').hidden=false;});
 select('drunk');requestAnimationFrame(loop);
}catch(error){console.error('Game initialization failed',error);$('error').hidden=false;$('selection').hidden=true;}
